47	interface OrderRow {
48	  id: number;
49	  code: string;
50	  customer_id: number;
51	  customer_username?: string | null;
52	  customer_name?: string | null;
53	  buyer_email?: string | null;
54	  buyer_telegram?: string | null;
55	  customer_notes?: string | null;
56	  product_snapshot: {
57	    id: number;
58	    name: string;
59	    category?: string;
60	  };
61	  variant_snapshot: {
62	    id: number;
63	    name: string;
64	    price: number;
65	  };
66	  quantity: number;
67	  total: number;
68	  currency: string;
69	  state: string;
70	  assigned_account_id?: number | null;
71	  assigned_account_label?: string | null;
72	  assigned_account_email?: string | null;
73	  assigned_account_password?: string | null;
74	  assigned_profile_name?: string | null;
75	  assigned_profile_pin?: string | null;
76	  supplier_id?: string | null;
77	  supplier_name?: string | null;
78	  supplier_handle?: string | null;
79	  deposit_batch_code?: string | null;
80	  is_supplier_stock?: boolean;
81	  origin_label?: string | null;
82	  warranty_expiration?: string | null;
83	  subscription_status?: string | null;
84	  payment_method?: string | null;
85	  payment_reference?: string | null;
86	  payment_channel?: string | null;
87	  payment_sender_name?: string | null;
88	  proof_submitted_at?: string | null;
89	  expires_at?: string | null;
90	  units?: any[];
91	  assigned_credentials_preview?: string | null;
92	  delivery_payload?: any;
93	  created_at: string;
94	}
95	
96	const FILTER_TABS = [
97	  { id: "ALL", label: "All Orders" },
98	  { id: "PENDING_MANUAL_VERIFICATION", label: "Pending Manual Verification" },
99	  { id: "DELIVERED", label: "Delivered" },
100	  { id: "REPLACED", label: "Replaced" },
101	  { id: "PAID", label: "Paid" },
102	  { id: "PROCESSING", label: "Processing" },
103	  { id: "CANCELLED", label: "Cancelled" },
104	];
105	
106	function SupplierOriginTag({
107	  isSupplier,
108	  supplierHandle,
109	}: {
110	  isSupplier?: boolean;
111	  supplierHandle?: string | null;
112	}) {
113	  if (isSupplier) {
114	    return (
115	      <div className="flex items-center gap-1 text-[10px] font-mono text-emerald-500 dark:text-emerald-400 mt-0.5 truncate">
116	        <span className="text-muted-foreground/60 font-sans">↳</span>
117	        <span className="inline-flex items-center gap-1 px-1.5 py-0.2 rounded bg-emerald-500/10 border border-emerald-500/20">
118	          <Boxes className="w-2.5 h-2.5 text-emerald-400 shrink-0" />
119	          <span className="truncate max-w-[110px]">{supplierHandle || "@partner"}</span>
120	        </span>
121	      </div>
122	    );
123	  }
124	  return null;
125	}
126	
127	export default function AdminOrdersPage() {
128	  const router = useRouter();
129	  const toast = useToast();
130	  const [orders, setOrders] = useState<OrderRow[]>([]);
131	  const [selectedOrderIds, setSelectedOrderIds] = useState<string[]>([]);
132	  const [selectedDetailOrder, setSelectedDetailOrder] = useState<OrderRow | null>(null);
133	  const [isPurging, setIsPurging] = useState(false);
134	  const [stats, setStats] = useState({ total: 0, delivered: 0, replaced: 0, pending: 0, verificationPending: 0 });
135	  const [stateFilter, setStateFilter] = useState("ALL");
136	  const [searchQuery, setSearchQuery] = useState("");
137	  const [replacingId, setReplacingId] = useState<number | null>(null);
138	  const [approvingId, setApprovingId] = useState<number | null>(null);
139	  const [rejectModalOrder, setRejectModalOrder] = useState<OrderRow | null>(null);
140	  const [rejectReason, setRejectReason] = useState("Payment proof could not be verified in e-wallet.");
141	  const [isRejecting, setIsRejecting] = useState(false);
142	
143	  function recalcStats(orderList: OrderRow[]) {
144	    let totalOrders = orderList.length;
145	    let deliveredOrders = 0;
146	    let replacementOrders = 0;
147	    let pendingOrders = 0;
148	    let verificationPendingOrders = 0;
149	
150	    for (const r of orderList) {
151	      if (r.state === "DELIVERED" || r.state === "COMPLETED") deliveredOrders++;
152	      else if (r.state === "REPLACED" || r.state === "REPLACEMENT_PENDING") replacementOrders++;
153	      else if (r.state === "PENDING_MANUAL_VERIFICATION") {
154	        verificationPendingOrders++;
155	        pendingOrders++;
156	      } else if (r.state === "PAID" || r.state === "PROCESSING" || r.state === "AWAITING_PAYMENT") {
157	        pendingOrders++;
158	      }
159	    }
160	
161	    setStats({
162	      total: totalOrders,
163	      delivered: deliveredOrders,
164	      replaced: replacementOrders,
165	      pending: pendingOrders,
166	      verificationPending: verificationPendingOrders,
167	    });
168	  }
169	
170	  // Masked password reveals & copy indicators
171	  const [revealedPasswords, setRevealedPasswords] = useState<Record<number, boolean>>({});
172	  const [copiedStates, setCopiedStates] = useState<Record<string, boolean>>({});
173	
174	  // Real-time newly arrived orders alert state & tracking ref
175	  const [newlyArrivedIds, setNewlyArrivedIds] = useState<Set<number>>(new Set());
176	  const knownOrderIdsRef = useRef<Set<number>>(new Set());
177	  const initialLoadDoneRef = useRef(false);
178	
179	  const queryClient = useQueryClient();
180	
181	  const ordersUrl =
182	    stateFilter !== "ALL"
183	      ? `/api/admin/orders?state=${stateFilter}`
184	      : "/api/admin/orders";
185	
186	  // Mounted TanStack Query: Authoritative admin orders with cancellation, window focus & reconnect refetch
187	  const {
188	    data: queryOrdersData,
189	    isLoading: queryLoading,
190	    isFetching: isSyncing,
191	    refetch: syncOrders,
192	  } = useQuery({
193	    queryKey: [...queryKeys.adminOrders(), stateFilter],
194	    queryFn: async ({ signal }) => {
195	      const res = await fetch(ordersUrl, {
196	        credentials: "include",
197	        signal,
198	      });
199	      if (!res.ok) throw new Error("Failed to load orders");
200	      return res.json() as Promise<{ orders?: OrderRow[]; stats?: any }>;
201	    },
202	    placeholderData: keepPreviousData,
203	    refetchOnWindowFocus: true,
204	    refetchOnReconnect: true,
205	    staleTime: 5000,
206	  });
207	
208	  const loading = queryLoading && !queryOrdersData;
209	
210	  useEffect(() => {
211	    if (queryOrdersData?.orders) {
212	      const isSubsequentPoll = initialLoadDoneRef.current;
213	      const freshArrivedIds: number[] = [];
214	
215	      for (const ord of queryOrdersData.orders) {
216	        if (isSubsequentPoll && !knownOrderIdsRef.current.has(ord.id)) {
217	          if (
218	            ord.state === "PENDING_MANUAL_VERIFICATION" ||
219	            ord.state === "PENDING" ||
220	            ord.state === "AWAITING_PAYMENT"
221	          ) {
222	            freshArrivedIds.push(ord.id);
223	          }
224	        }
225	      }
226	
227	      if (freshArrivedIds.length > 0) {
228	        playNotificationSound();
229	        toast.info(`${freshArrivedIds.length} new order(s) arrived!`);
230	        setNewlyArrivedIds((prev) => new Set([...prev, ...freshArrivedIds]));
231	
232	        // Highlight / pulse row for 3 seconds then clean up
233	        setTimeout(() => {
234	          setNewlyArrivedIds((prev) => {
235	            const next = new Set(prev);
236	            freshArrivedIds.forEach((id) => next.delete(id));
237	            return next;
238	          });
239	        }, 3000);
240	      }
241	
242	      // Add all order IDs to known set
243	      queryOrdersData.orders.forEach((ord) => knownOrderIdsRef.current.add(ord.id));
244	      initialLoadDoneRef.current = true;
245	      setOrders(queryOrdersData.orders);
246	    }
247	    if (queryOrdersData?.stats) {
248	      setStats(queryOrdersData.stats);
249	    }
250	  }, [queryOrdersData]);
251	
252	  async function loadOrders(invalidateAfter = false) {
253	    if (invalidateAfter) {
254	      queryClient.invalidateQueries({ queryKey: queryKeys.adminOrders() });
255	      invalidateResource(["orders", "catalog", "customer_vault"]);
256	    } else {
257	      await syncOrders();
258	    }
259	  }
260	
261	  function togglePassword(id: number) {
262	    setRevealedPasswords((prev) => ({ ...prev, [id]: !prev[id] }));
263	  }
264	
265	  function handleCopy(text: string, key: string) {
266	    navigator.clipboard.writeText(text);
267	    setCopiedStates((prev) => ({ ...prev, [key]: true }));
268	    setTimeout(() => {
269	      setCopiedStates((prev) => ({ ...prev, [key]: false }));
270	    }, 2000);
271	  }
272	
273	
274	
275	  function renderPaymentChannelBadge(channel?: string | null) {
276	    const ch = (channel || "").toLowerCase();
277	    if (ch.includes("gcash")) {
278	      return (
279	        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-bold bg-blue-500/15 text-blue-400 border border-blue-500/30 shadow-sm shadow-blue-950/20">
280	          <Smartphone className="w-3.5 h-3.5 text-blue-400" />
281	          <span>GCash</span>
282	        </span>
283	      );
284	    }
285	    if (ch.includes("maya")) {
286	      return (
287	        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-bold bg-emerald-500/15 text-emerald-400 border border-emerald-500/30 shadow-sm shadow-emerald-950/20">
288	          <Wallet className="w-3.5 h-3.5 text-emerald-400" />
289	          <span>Maya</span>
290	        </span>
291	      );
292	    }
293	    if (ch.includes("maribank")) {
294	      return (
295	        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-bold bg-sky-500/15 text-sky-400 border border-sky-500/30 shadow-sm shadow-sky-950/20">
296	          <Building2 className="w-3.5 h-3.5 text-sky-400" />
297	          <span>MariBank</span>
298	        </span>
299	      );
300	    }
301	    return (
302	      <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-semibold bg-neutral-100 dark:bg-[#20232C] text-neutral-700 dark:text-neutral-300 border border-neutral-200 dark:border-white/10">
303	        <CreditCard className="w-3.5 h-3.5 text-neutral-400" />
304	        <span>{channel || "Manual"}</span>
305	      </span>
306	    );
307	  }
308	
309	  async function handleWarrantyReplacement(order: OrderRow) {
310	    const confirmMsg = `Issue 1-Click Warranty Replacement for Order ${order.code} (${order.product_snapshot?.name})?\n\nThis marks the current credential as REPLACED and automatically provisions the next AVAILABLE unit from the Vault.`;
311	    if (!confirm(confirmMsg)) return;
312	
313	    setReplacingId(order.id);
314	    try {
315	      const res = await fetch("/api/admin/orders", {
316	        method: "POST",
317	        headers: { "Content-Type": "application/json" },
318	        credentials: "include",
319	        body: JSON.stringify({
320	          action: "replace",
321	          orderId: order.id,
322	          order_id: order.id,
323	        }),
324	      });
325	
326	      const data = await res.json();
327	      if (!res.ok || !data.success) {
328	        throw new Error(data?.error || "Failed to issue warranty replacement");
329	      }
330	
331	      toast.success(data.message || "1-Click warranty replacement completed!");
332	      loadOrders(true);
333	    } catch (err: any) {
334	      toast.error(err?.message || "Failed to replace account");
335	    } finally {
336	      setReplacingId(null);
337	    }
338	  }
339	
340	  async function handleApproveAndDeliver(order: OrderRow) {
341	    const confirmMsg = `Approve payment & instantly deliver account for Order ${order.code}?\n\nThis assigns the next available vault account and sends credentials directly to the customer.`;
342	    if (!confirm(confirmMsg)) return;
343	
344	    setApprovingId(order.id);
345	    try {
346	      const res = await fetch("/api/admin/orders", {
347	        method: "POST",
348	        headers: { "Content-Type": "application/json" },
349	        credentials: "include",
350	        body: JSON.stringify({
351	          action: "approve_and_deliver",
352	          orderId: order.id,
353	          order_id: order.id,
354	        }),
355	      });
356	
357	      const data = await res.json();
358	      if (!res.ok || !data.success) {
359	        throw new Error(data?.error || "Failed to approve and deliver order");
360	      }
361	
362	      toast.success(data.message || "Order approved & account delivered!");
363	      loadOrders(true);
364	    } catch (err: any) {
365	      toast.error(err?.message || "Failed to deliver account");
366	    } finally {
367	      setApprovingId(null);
368	    }
369	  }
370	
371	  async function handleApproveManualOrder(order: OrderRow) {
372	    const confirmMsg = `Approve Manual Payment for Order ${order.code}?\n\n• Product: ${order.product_snapshot?.name}\n• Total: ₱${Number(order.total || 0).toFixed(2)}\n• Channel: ${order.payment_channel || "Manual"}\n• Reference: ${order.payment_reference || "None"}\n\nThis will decrypt vault credentials, transition the order to DELIVERED/COMPLETED, and deliver credentials instantly to the buyer.`;
373	    if (!confirm(confirmMsg)) return;
374	
375	    setApprovingId(order.id);
376	    try {
377	      const res = await fetch("/api/admin/orders", {
378	        method: "POST",
379	        headers: { "Content-Type": "application/json" },
380	        credentials: "include",
381	        body: JSON.stringify({
382	          action: "approve_manual",
383	          orderId: order.id,
384	          order_id: order.id,
385	        }),
386	      });
387	
388	      const data = await res.json();
389	      if (!res.ok || !data.success) {
390	        throw new Error(data?.error || "Failed to approve manual order");
391	      }
392	
393	      toast.success(data.message || `Order ${order.code} approved and credentials dispensed!`);
394	      loadOrders(true);
395	    } catch (err: any) {
396	      toast.error(err?.message || "Failed to approve order");
397	    } finally {
398	      setApprovingId(null);
399	    }
400	  }
401	
402	  async function handleRejectManualOrder(order: OrderRow): Promise<void> {
403	    setRejectModalOrder(order);
404	    setRejectReason("Payment proof could not be verified in e-wallet.");
405	  }
406	
407	  async function submitRejectManualOrder() {
408	    if (!rejectModalOrder) return;
409	
410	    setIsRejecting(true);
411	    try {
412	      const res = await fetch("/api/admin/orders", {
413	        method: "POST",
414	        headers: { "Content-Type": "application/json" },
415	        credentials: "include",
416	        body: JSON.stringify({
417	          action: "reject_manual",
418	          orderId: rejectModalOrder.id,
419	          order_id: rejectModalOrder.id,
420	          reason: rejectReason.trim() || "Payment verification failed",
421	        }),
422	      });
423	
424	      const data = await res.json();
425	      if (!res.ok || !data.success) {
426	        throw new Error(data?.error || "Failed to reject manual order");
427	      }
428	
429	      toast.success(data.message || `Order ${rejectModalOrder.code} rejected and inventory hold released.`);
430	      setRejectModalOrder(null);
431	      if (selectedDetailOrder?.id === rejectModalOrder.id) {
432	        setSelectedDetailOrder(null);
433	      }
434	      loadOrders(true);
435	    } catch (err: any) {
436	      toast.error(err?.message || "Failed to reject order");
437	    } finally {
438	      setIsRejecting(false);
439	    }
440	  }
441	
442	  async function handleBatchPurge() {
443	    if (selectedOrderIds.length === 0) return;
444	    const count = selectedOrderIds.length;
445	    const confirmMsg = `Are you sure you want to permanently delete and purge ${count} selected order(s)?\n\nThis will remove orders and delete associated records. Only unfulfilled reservations are released back to AVAILABLE inventory, while already-delivered credentials remain permanently consumed. This action cannot be undone.`;
446	    if (!window.confirm(confirmMsg)) return;
447	
448	    setIsPurging(true);
449	    try {
450	      const res = await fetch("/api/admin/orders", {
451	        method: "DELETE",
452	        headers: { "Content-Type": "application/json" },
453	        credentials: "include",
454	        body: JSON.stringify({ orderIds: selectedOrderIds }),
455	      });
456	
457	      const data = await res.json();
458	      if (!res.ok || !data.success) {
459	        throw new Error(data?.error || "Failed to purge selected orders");
460	      }
461	
462	      const deletedIds: string[] =
463	        Array.isArray(data.deletedIds) && data.deletedIds.length > 0
464	          ? data.deletedIds.map(String)
465	          : selectedOrderIds;
466	
467	      toast.success(`Successfully purged ${deletedIds.length} order(s).`);
468	
469	      const deletedIdSet = new Set(deletedIds);
470	      setOrders((prev) => {
471	        const nextOrders = prev.filter((o) => !deletedIdSet.has(String(o.id)));
472	        recalcStats(nextOrders);
473	        return nextOrders;
474	      });
475	      setSelectedOrderIds([]);
476	      router.refresh();
477	    } catch (err: any) {
478	      toast.error(err?.message || "Failed to purge orders");
479	    } finally {
480	      setIsPurging(false);
481	    }
482	  }
483	
484	  async function handleDeleteSingleOrder(order: OrderRow) {
485	    const confirmMsg = `Are you sure you want to delete order ${order.code} (#${order.id})?\n\nThis will permanently remove the order and delete associated records. Only unfulfilled reservations are released back to AVAILABLE inventory, while already-delivered credentials remain permanently consumed.`;
486	    if (!window.confirm(confirmMsg)) return;
487	
488	    setIsPurging(true);
489	    try {
490	      const res = await fetch("/api/admin/orders", {
491	        method: "DELETE",
492	        headers: { "Content-Type": "application/json" },
493	        credentials: "include",
494	        body: JSON.stringify({ orderIds: [String(order.id)] }),
495	      });
496	
497	      const data = await res.json();
498	      if (!res.ok || !data.success) {
499	        throw new Error(data?.error || `Failed to delete order ${order.code}`);
500	      }
501	
502	      toast.success(`Order ${order.code} deleted.`);
503	
504	      const idStr = String(order.id);
505	      setOrders((prev) => {
506	        const nextOrders = prev.filter((o) => String(o.id) !== idStr);
507	        recalcStats(nextOrders);
508	        return nextOrders;
509	      });
510	      setSelectedOrderIds((prev) => prev.filter((id) => id !== idStr));
511	      router.refresh();
512	    } catch (err: any) {
513	      toast.error(err?.message || "Failed to delete order");
514	    } finally {
515	      setIsPurging(false);
516	    }
517	  }
518	
519	  function getRemainingDays(expirationDateStr?: string | null) {
520	    if (!expirationDateStr) return "No Warranty";
521	    const exp = new Date(expirationDateStr);
522	    const diffDays = Math.ceil((exp.getTime() - Date.now()) / (1000 * 60 * 60 * 24));
523	    if (diffDays < 0) return "Expired";
524	    if (diffDays === 0) return "Expires Today";
525	    return `${diffDays} Days Left`;
526	  }
527	
528	  const filteredOrders = orders.filter((ord) => {
529	    if (!searchQuery.trim()) return true;
530	    const q = searchQuery.toLowerCase();
531	    return (
532	      ord.code?.toLowerCase().includes(q) ||
533	      ord.customer_username?.toLowerCase().includes(q) ||
534	      String(ord.customer_id).includes(q) ||
535	      ord.buyer_email?.toLowerCase().includes(q) ||
536	      ord.buyer_telegram?.toLowerCase().includes(q) ||
537	      ord.payment_reference?.toLowerCase().includes(q) ||
538	      ord.payment_sender_name?.toLowerCase().includes(q) ||
539	      ord.payment_channel?.toLowerCase().includes(q) ||
540	      ord.product_snapshot?.name?.toLowerCase().includes(q) ||
541	      ord.assigned_account_email?.toLowerCase().includes(q) ||
542	      ord.assigned_credentials_preview?.toLowerCase().includes(q)
543	    );
544	  });
545	
546	  const isPendingVerificationTab = stateFilter === "PENDING_MANUAL_VERIFICATION";
547	
548	  return (
549	    <div className="space-y-5 w-full">
550	      {/* Top Header */}
551	      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 border-b border-border pb-5">
552	        <div>
553	          <div className="flex items-center space-x-2.5">
554	            <div className="w-8 h-8 rounded-xl bg-sky-500/10 border border-sky-500/25 flex items-center justify-center">
555	              <ShoppingBag className="w-4 h-4 text-sky-500" />
556	            </div>
557	            <h1 className="text-xl sm:text-2xl font-semibold tracking-tight text-foreground font-sans">
558	              Orders
559	            </h1>
560	          </div>
561	          <p className="text-sm text-muted-foreground mt-1">
562	            Search customer orders, manual payment verification queue, and assigned credentials.
563	          </p>
564	        </div>
565	
566	        <div className="flex items-center space-x-3">
567	          <button
568	            onClick={() => { void loadOrders(); }}
569	            disabled={loading}
570	            className="flex items-center space-x-1.5 px-3 py-2 rounded-xl bg-card border border-border hover:border-border/80 text-xs font-medium text-foreground transition-colors cursor-pointer"
571	          >
572	            <RefreshCw className={`w-3.5 h-3.5 ${loading ? "animate-spin text-sky-400" : ""}`} />
573	            <span>Sync</span>
574	          </button>
575	        </div>
576	      </div>
