"use client";

import React, { useState, useEffect, useMemo, useCallback, useRef } from "react";
import { useRouter } from "next/navigation";
import {
  ShoppingBag,
  RefreshCw,
  Loader2,
  CheckCircle2,
  RotateCcw,
  Eye,
  EyeOff,
  Copy,
  Check,
  User,
  ShieldCheck,
  Boxes,
  Smartphone,
  Wallet,
  Calendar,
  Send,
  Zap,
  Search,
  Clock,
  AlertTriangle,
  Building2,
  ExternalLink,
  Mail,
  MessageCircle,
  XCircle,
  CreditCard,
  Trash2,
  Package,
  AlertCircle,
} from "lucide-react";
import { useToast } from "@/app/components/Toast";
import { AnimatedTabs } from "@/components/ui/tabs";
import { StatusBadge } from "@/components/ui/badge";
import { ActionDropdown } from "@/components/ui/dropdown-menu";
import { AnimatedModal } from "@/components/ui/modal";
import { useLiveSync, playNotificationSound, invalidateResource } from "@/src/hooks/use-live-sync";
import { useQuery, keepPreviousData, useQueryClient } from "@tanstack/react-query";
import { queryKeys } from "@/src/lib/query-keys";
import { OrderDetailsModal } from "@/components/admin/OrderDetailsModal";
import { OrderCountdown } from "@/components/admin/OrderCountdown";

interface OrderRow {
  id: number;
  code: string;
  customer_id: number;
  customer_username?: string | null;
  customer_name?: string | null;
  buyer_email?: string | null;
  buyer_telegram?: string | null;
  customer_notes?: string | null;
  product_snapshot: {
    id: number;
    name: string;
    category?: string;
  };
  variant_snapshot: {
    id: number;
    name: string;
    price: number;
  };
  quantity: number;
  total: number;
  currency: string;
  state: string;
  assigned_account_id?: number | null;
  assigned_account_label?: string | null;
  assigned_account_email?: string | null;
  assigned_account_password?: string | null;
  assigned_profile_name?: string | null;
  assigned_profile_pin?: string | null;
  supplier_id?: string | null;
  supplier_name?: string | null;
  supplier_handle?: string | null;
  deposit_batch_code?: string | null;
  is_supplier_stock?: boolean;
  origin_label?: string | null;
  warranty_expiration?: string | null;
  subscription_status?: string | null;
  payment_method?: string | null;
  payment_reference?: string | null;
  payment_channel?: string | null;
  payment_sender_name?: string | null;
  proof_submitted_at?: string | null;
  expires_at?: string | null;
  units?: any[];
  assigned_credentials_preview?: string | null;
  delivery_payload?: any;
  created_at: string;
}

const FILTER_TABS = [
  { id: "ALL", label: "All Orders" },
  { id: "PENDING_MANUAL_VERIFICATION", label: "Pending Manual Verification" },
  { id: "DELIVERED", label: "Delivered" },
  { id: "REPLACED", label: "Replaced" },
  { id: "PAID", label: "Paid" },
  { id: "PROCESSING", label: "Processing" },
  { id: "CANCELLED", label: "Cancelled" },
];

function SupplierOriginTag({
  isSupplier,
  supplierHandle,
}: {
  isSupplier?: boolean;
  supplierHandle?: string | null;
}) {
  if (isSupplier) {
    return (
      <div className="flex items-center gap-1 text-[10px] font-mono text-emerald-500 dark:text-emerald-400 mt-0.5 truncate">
        <span className="text-muted-foreground/60 font-sans">↳</span>
        <span className="inline-flex items-center gap-1 px-1.5 py-0.2 rounded bg-emerald-500/10 border border-emerald-500/20">
          <Boxes className="w-2.5 h-2.5 text-emerald-400 shrink-0" />
          <span className="truncate max-w-[110px]">{supplierHandle || "@partner"}</span>
        </span>
      </div>
    );
  }
  return null;
}

export default function AdminOrdersPage() {
  const router = useRouter();
  const toast = useToast();
  const [orders, setOrders] = useState<OrderRow[]>([]);
  const [selectedOrderIds, setSelectedOrderIds] = useState<string[]>([]);
  const [selectedDetailOrder, setSelectedDetailOrder] = useState<OrderRow | null>(null);
  const [isPurging, setIsPurging] = useState(false);
  const [stats, setStats] = useState({ total: 0, delivered: 0, replaced: 0, pending: 0, verificationPending: 0 });
  const [stateFilter, setStateFilter] = useState("ALL");
  const [searchQuery, setSearchQuery] = useState("");
  const [replacingId, setReplacingId] = useState<number | null>(null);
  const [approvingId, setApprovingId] = useState<number | null>(null);
  const [rejectModalOrder, setRejectModalOrder] = useState<OrderRow | null>(null);
  const [rejectReason, setRejectReason] = useState("Payment proof could not be verified in e-wallet.");
  const [isRejecting, setIsRejecting] = useState(false);

  function recalcStats(orderList: OrderRow[]) {
    let totalOrders = orderList.length;
    let deliveredOrders = 0;
    let replacementOrders = 0;
    let pendingOrders = 0;
    let verificationPendingOrders = 0;

    for (const r of orderList) {
      if (r.state === "DELIVERED" || r.state === "COMPLETED") deliveredOrders++;
      else if (r.state === "REPLACED" || r.state === "REPLACEMENT_PENDING") replacementOrders++;
      else if (r.state === "PENDING_MANUAL_VERIFICATION") {
        verificationPendingOrders++;
        pendingOrders++;
      } else if (r.state === "PAID" || r.state === "PROCESSING" || r.state === "AWAITING_PAYMENT") {
        pendingOrders++;
      }
    }

    setStats({
      total: totalOrders,
      delivered: deliveredOrders,
      replaced: replacementOrders,
      pending: pendingOrders,
      verificationPending: verificationPendingOrders,
    });
  }

  // Masked password reveals & copy indicators
  const [revealedPasswords, setRevealedPasswords] = useState<Record<number, boolean>>({});
  const [copiedStates, setCopiedStates] = useState<Record<string, boolean>>({});

  // Real-time newly arrived orders alert state & tracking ref
  const [newlyArrivedIds, setNewlyArrivedIds] = useState<Set<number>>(new Set());
  const knownOrderIdsRef = useRef<Set<number>>(new Set());
  const initialLoadDoneRef = useRef(false);

  const queryClient = useQueryClient();

  const ordersUrl =
    stateFilter !== "ALL"
      ? `/api/admin/orders?state=${stateFilter}`
      : "/api/admin/orders";

  // Mounted TanStack Query: Authoritative admin orders with cancellation, window focus & reconnect refetch
  const {
    data: queryOrdersData,
    isLoading: queryLoading,
    isFetching: isSyncing,
    refetch: syncOrders,
  } = useQuery({
    queryKey: [...queryKeys.adminOrders(), stateFilter],
    queryFn: async ({ signal }) => {
      const res = await fetch(ordersUrl, {
        credentials: "include",
        signal,
      });
      if (!res.ok) throw new Error("Failed to load orders");
      return res.json() as Promise<{ orders?: OrderRow[]; stats?: any }>;
    },
    placeholderData: keepPreviousData,
    refetchOnWindowFocus: true,
    refetchOnReconnect: true,
    staleTime: 5000,
  });

  const loading = queryLoading && !queryOrdersData;

  useEffect(() => {
    if (queryOrdersData?.orders) {
      const isSubsequentPoll = initialLoadDoneRef.current;
      const freshArrivedIds: number[] = [];

      for (const ord of queryOrdersData.orders) {
        if (isSubsequentPoll && !knownOrderIdsRef.current.has(ord.id)) {
          if (
            ord.state === "PENDING_MANUAL_VERIFICATION" ||
            ord.state === "PENDING" ||
            ord.state === "AWAITING_PAYMENT"
          ) {
            freshArrivedIds.push(ord.id);
          }
        }
      }

      if (freshArrivedIds.length > 0) {
        playNotificationSound();
        toast.info(`${freshArrivedIds.length} new order(s) arrived!`);
        setNewlyArrivedIds((prev) => new Set([...prev, ...freshArrivedIds]));

        // Highlight / pulse row for 3 seconds then clean up
        setTimeout(() => {
          setNewlyArrivedIds((prev) => {
            const next = new Set(prev);
            freshArrivedIds.forEach((id) => next.delete(id));
            return next;
          });
        }, 3000);
      }

      // Add all order IDs to known set
      queryOrdersData.orders.forEach((ord) => knownOrderIdsRef.current.add(ord.id));
      initialLoadDoneRef.current = true;
      setOrders(queryOrdersData.orders);
    }
    if (queryOrdersData?.stats) {
      setStats(queryOrdersData.stats);
    }
  }, [queryOrdersData]);

