const isPendingVerificationTab = stateFilter === "PENDING_MANUAL_VERIFICATION";

function csvCell(value: unknown): string {
  let s = value === null || value === undefined ? "" : String(value);
  // Neutralize spreadsheet formula injection
  if (/^[=+\-@\t\r]/.test(s)) s = `'${s}`;
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

function handleExportCsv() {
  if (filteredOrders.length === 0) {
    toast.info("No orders to export.");
    return;
  }
  // Credentials (passwords/PINs) intentionally excluded.
  const header = [
    "Order Code", "Created At", "State", "Product", "Variant", "Quantity", "Total", "Currency",
    "Customer ID", "Customer Username", "Buyer Email", "Buyer Telegram",
    "Payment Channel", "Payment Reference", "Payment Sender", "Warranty Expiration", "Supplier",
  ];
  const rows = filteredOrders.map((o) => [
    o.code,
    o.created_at,
    o.state,
    o.product_snapshot?.name,
    o.variant_snapshot?.name,
    o.quantity,
    o.total,
    o.currency,
    o.customer_id,
    o.customer_username,
    o.buyer_email,
    o.buyer_telegram,
    o.payment_channel,
    o.payment_reference,
    o.payment_sender_name,
    o.warranty_expiration,
    o.supplier_name || o.supplier_handle,
  ]);
  const csv = [header, ...rows].map((r) => r.map(csvCell).join(",")).join("\r\n");
  const blob = new Blob(["﻿" + csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `orders-${stateFilter.toLowerCase()}-${new Date().toISOString().slice(0, 10)}.csv`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
  toast.success(`Exported ${filteredOrders.length} order(s).`);
}

