"use client";

import React, { useState, useEffect, useMemo, useCallback, useRef } from "react";
import { useRouter } from "next/navigation";
import {
  ShoppingBag,
  RefreshCw,
  Loader2,
  CheckCircle2,
  RotateCcw,
  Eye,
  EyeOff,
  Copy,
  Check,
  User,
  ShieldCheck,
  Boxes,
  Smartphone,
  Wallet,
  Calendar,
  Send,
  Zap,
  Search,
  Clock,
  AlertTriangle,
  Building2,
  ExternalLink,
  Mail,
  MessageCircle,
  XCircle,
  CreditCard,
  Trash2,
  Package,
  AlertCircle,
  Download,
} from "lucide-react";
import { useToast } from "@/app/components/Toast";
import { AnimatedTabs } from "@/components/ui/tabs";
import { StatusBadge } from "@/components/ui/badge";
import { ActionDropdown } from "@/components/ui/dropdown-menu";
import { AnimatedModal } from "@/components/ui/modal";
import { useLiveSync, playNotificationSound, invalidateResource } from "@/src/hooks/use-live-sync";
import { useQuery, keepPreviousData, useQueryClient } from "@tanstack/react-query";
import { queryKeys } from "@/src/lib/query-keys";
import { OrderDetailsModal } from "@/components/admin/OrderDetailsModal";
import { OrderCountdown } from "@/components/admin/OrderCountdown";

interface OrderRow {
  id: number;
  code: string;
  customer_id: number;
  customer_username?: string | null;
  customer_name?: string | null;
  buyer_email?: string | null;
  buyer_telegram?: string | null;
  customer_notes?: string | null;
  product_snapshot: {
    id: number;
    name: string;
    category?: string;
  };
  variant_snapshot: {
    id: number;
    name: string;
    price: number;
  };
  quantity: number;
  total: number;
  currency: string;
  state: string;
  assigned_account_id?: number | null;
  assigned_account_label?: string | null;
  assigned_account_email?: string | null;
  assigned_account_password?: string | null;
  assigned_profile_name?: string | null;
  assigned_profile_pin?: string | null;
  supplier_id?: string | null;
  supplier_name?: string | null;
  supplier_handle?: string | null;
  deposit_batch_code?: string | null;
  is_supplier_stock?: boolean;
  origin_label?: string | null;
  warranty_expiration?: string | null;
  subscription_status?: string | null;
  payment_method?: string | null;
  payment_reference?: string | null;
  payment_channel?: string | null;
  payment_sender_name?: string | null;
  proof_submitted_at?: string | null;
  expires_at?: string | null;
  units?: any[];
  assigned_credentials_preview?: string | null;
  delivery_payload?: any;
  created_at: string;
}

const FILTER_TABS = [
  { id: "ALL", label: "All Orders" },
  { id: "PENDING_MANUAL_VERIFICATION", label: "Pending Manual Verification" },
  { id: "DELIVERED", label: "Delivered" },
  { id: "REPLACED", label: "Replaced" },
  { id: "PAID", label: "Paid" },
  { id: "PROCESSING", label: "Processing" },
  { id: "CANCELLED", label: "Cancelled" },
];

function SupplierOriginTag({
  isSupplier,
  supplierHandle,
}: {
  isSupplier?: boolean;
  supplierHandle?: string | null;
}) {
  if (isSupplier) {
    return (
      <div className="flex items-center gap-1 text-[10px] font-mono text-emerald-500 dark:text-emerald-400 mt-0.5 truncate">
        <span className="text-muted-foreground/60 font-sans">↳</span>
        <span className="inline-flex items-center gap-1 px-1.5 py-0.2 rounded bg-emerald-500/10 border border-emerald-500/20">
          <Boxes className="w-2.5 h-2.5 text-emerald-400 shrink-0" />
          <span className="truncate max-w-[110px]">{supplierHandle || "@partner"}</span>
        </span>
      </div>
    );
  }
  return null;
}

export default function AdminOrdersPage() {
  const router = useRouter();
  const toast = useToast();
  const [orders, setOrders] = useState<OrderRow[]>([]);
  const [selectedOrderIds, setSelectedOrderIds] = useState<string[]>([]);
  const [selectedDetailOrder, setSelectedDetailOrder] = useState<OrderRow | null>(null);
  const [isPurging, setIsPurging] = useState(false);
  const [stats, setStats] = useState({ total: 0, delivered: 0, replaced: 0, pending: 0, verificationPending: 0 });
  const [stateFilter, setStateFilter] = useState("ALL");
  const [searchQuery, setSearchQuery] = useState("");
  const [replacingId, setReplacingId] = useState<number | null>(null);
  const [approvingId, setApprovingId] = useState<number | null>(null);
  const [rejectModalOrder, setRejectModalOrder] = useState<OrderRow | null>(null);
  const [rejectReason, setRejectReason] = useState("Payment proof could not be verified in e-wallet.");
  const [isRejecting, setIsRejecting] = useState(false);

  function recalcStats(orderList: OrderRow[]) {
    let totalOrders = orderList.length;
    let deliveredOrders = 0;
    let replacementOrders = 0;
    let pendingOrders = 0;
    let verificationPendingOrders = 0;

    for (const r of orderList) {
      if (r.state === "DELIVERED" || r.state === "COMPLETED") deliveredOrders++;
      else if (r.state === "REPLACED" || r.state === "REPLACEMENT_PENDING") replacementOrders++;
      else if (r.state === "PENDING_MANUAL_VERIFICATION") {
        verificationPendingOrders++;
        pendingOrders++;
      } else if (r.state === "PAID" || r.state === "PROCESSING" || r.state === "AWAITING_PAYMENT") {
        pendingOrders++;
      }
    }

    setStats({
      total: totalOrders,
      delivered: deliveredOrders,
      replaced: replacementOrders,
      pending: pendingOrders,
      verificationPending: verificationPendingOrders,
    });
  }

  // Masked password reveals & copy indicators
  const [revealedPasswords, setRevealedPasswords] = useState<Record<number, boolean>>({});
  const [copiedStates, setCopiedStates] = useState<Record<string, boolean>>({});

  // Real-time newly arrived orders alert state & tracking ref
  const [newlyArrivedIds, setNewlyArrivedIds] = useState<Set<number>>(new Set());
  const knownOrderIdsRef = useRef<Set<number>>(new Set());
  const initialLoadDoneRef = useRef(false);

  const queryClient = useQueryClient();

  const ordersUrl =
    stateFilter !== "ALL"
      ? `/api/admin/orders?state=${stateFilter}`
      : "/api/admin/orders";

  // Mounted TanStack Query: Authoritative admin orders with cancellation, window focus & reconnect refetch
  const {
    data: queryOrdersData,
    isLoading: queryLoading,
    isFetching: isSyncing,
    refetch: syncOrders,
  } = useQuery({
    queryKey: [...queryKeys.adminOrders(), stateFilter],
    queryFn: async ({ signal }) => {
      const res = await fetch(ordersUrl, {
        credentials: "include",
        signal,
      });
      if (!res.ok) throw new Error("Failed to load orders");
      return res.json() as Promise<{ orders?: OrderRow[]; stats?: any }>;
    },
    placeholderData: keepPreviousData,
    refetchOnWindowFocus: true,
    refetchOnReconnect: true,
    staleTime: 5000,
  });

  const loading = queryLoading && !queryOrdersData;

  useEffect(() => {
    if (queryOrdersData?.orders) {
      const isSubsequentPoll = initialLoadDoneRef.current;
      const freshArrivedIds: number[] = [];

      for (const ord of queryOrdersData.orders) {
        if (isSubsequentPoll && !knownOrderIdsRef.current.has(ord.id)) {
          if (
            ord.state === "PENDING_MANUAL_VERIFICATION" ||
            ord.state === "PENDING" ||
            ord.state === "AWAITING_PAYMENT"
          ) {
            freshArrivedIds.push(ord.id);
          }
        }
      }

      if (freshArrivedIds.length > 0) {
        playNotificationSound();
        toast.info(`${freshArrivedIds.length} new order(s) arrived!`);
        setNewlyArrivedIds((prev) => new Set([...prev, ...freshArrivedIds]));

        // Highlight / pulse row for 3 seconds then clean up
        setTimeout(() => {
          setNewlyArrivedIds((prev) => {
            const next = new Set(prev);
            freshArrivedIds.forEach((id) => next.delete(id));
            return next;
          });
        }, 3000);
      }

      // Add all order IDs to known set
      queryOrdersData.orders.forEach((ord) => knownOrderIdsRef.current.add(ord.id));
      initialLoadDoneRef.current = true;
      setOrders(queryOrdersData.orders);
    }
    if (queryOrdersData?.stats) {
      setStats(queryOrdersData.stats);
    }
  }, [queryOrdersData]);

  async function loadOrders(invalidateAfter = false) {
    if (invalidateAfter) {
      queryClient.invalidateQueries({ queryKey: queryKeys.adminOrders() });
      invalidateResource(["orders", "catalog", "customer_vault"]);
    } else {
      await syncOrders();
    }
  }

  function togglePassword(id: number) {
    setRevealedPasswords((prev) => ({ ...prev, [id]: !prev[id] }));
  }

  function handleCopy(text: string, key: string) {
    navigator.clipboard.writeText(text);
    setCopiedStates((prev) => ({ ...prev, [key]: true }));
    setTimeout(() => {
      setCopiedStates((prev) => ({ ...prev, [key]: false }));
    }, 2000);
  }



  function renderPaymentChannelBadge(channel?: string | null) {
    const ch = (channel || "").toLowerCase();
    if (ch.includes("gcash")) {
      return (
        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-bold bg-blue-500/15 text-blue-400 border border-blue-500/30 shadow-sm shadow-blue-950/20">
          <Smartphone className="w-3.5 h-3.5 text-blue-400" />
          <span>GCash</span>
        </span>
      );
    }
    if (ch.includes("maya")) {
      return (
        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-bold bg-emerald-500/15 text-emerald-400 border border-emerald-500/30 shadow-sm shadow-emerald-950/20">
          <Wallet className="w-3.5 h-3.5 text-emerald-400" />
          <span>Maya</span>
        </span>
      );
    }
    if (ch.includes("maribank")) {
      return (
        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-bold bg-sky-500/15 text-sky-400 border border-sky-500/30 shadow-sm shadow-sky-950/20">
          <Building2 className="w-3.5 h-3.5 text-sky-400" />
          <span>MariBank</span>
        </span>
      );
    }
    return (
      <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-semibold bg-neutral-100 dark:bg-[#20232C] text-neutral-700 dark:text-neutral-300 border border-neutral-200 dark:border-white/10">
        <CreditCard className="w-3.5 h-3.5 text-neutral-400" />
        <span>{channel || "Manual"}</span>
      </span>
    );
  }

  async function handleWarrantyReplacement(order: OrderRow) {
    const confirmMsg = `Issue 1-Click Warranty Replacement for Order ${order.code} (${order.product_snapshot?.name})?\n\nThis marks the current credential as REPLACED and automatically provisions the next AVAILABLE unit from the Vault.`;
    if (!confirm(confirmMsg)) return;

    setReplacingId(order.id);
    try {
      const res = await fetch("/api/admin/orders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          action: "replace",
          orderId: order.id,
          order_id: order.id,
        }),
      });

      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data?.error || "Failed to issue warranty replacement");
      }

      toast.success(data.message || "1-Click warranty replacement completed!");
      loadOrders(true);
    } catch (err: any) {
      toast.error(err?.message || "Failed to replace account");
    } finally {
      setReplacingId(null);
    }
  }

  async function handleApproveAndDeliver(order: OrderRow) {
    const confirmMsg = `Approve payment & instantly deliver account for Order ${order.code}?\n\nThis assigns the next available vault account and sends credentials directly to the customer.`;
    if (!confirm(confirmMsg)) return;

    setApprovingId(order.id);
    try {
      const res = await fetch("/api/admin/orders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          action: "approve_and_deliver",
          orderId: order.id,
          order_id: order.id,
        }),
      });

      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data?.error || "Failed to approve and deliver order");
      }

      toast.success(data.message || "Order approved & account delivered!");
      loadOrders(true);
    } catch (err: any) {
      toast.error(err?.message || "Failed to deliver account");
    } finally {
      setApprovingId(null);
    }
  }

  async function handleApproveManualOrder(order: OrderRow) {
    const confirmMsg = `Approve Manual Payment for Order ${order.code}?\n\n• Product: ${order.product_snapshot?.name}\n• Total: ₱${Number(order.total || 0).toFixed(2)}\n• Channel: ${order.payment_channel || "Manual"}\n• Reference: ${order.payment_reference || "None"}\n\nThis will decrypt vault credentials, transition the order to DELIVERED/COMPLETED, and deliver credentials instantly to the buyer.`;
    if (!confirm(confirmMsg)) return;

    setApprovingId(order.id);
    try {
      const res = await fetch("/api/admin/orders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          action: "approve_manual",
          orderId: order.id,
          order_id: order.id,
        }),
      });

      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data?.error || "Failed to approve manual order");
      }

      toast.success(data.message || `Order ${order.code} approved and credentials dispensed!`);
      loadOrders(true);
    } catch (err: any) {
      toast.error(err?.message || "Failed to approve order");
    } finally {
      setApprovingId(null);
    }
  }

  async function handleRejectManualOrder(order: OrderRow): Promise<void> {
    setRejectModalOrder(order);
    setRejectReason("Payment proof could not be verified in e-wallet.");
  }

  async function submitRejectManualOrder() {
    if (!rejectModalOrder) return;

    setIsRejecting(true);
    try {
      const res = await fetch("/api/admin/orders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          action: "reject_manual",
          orderId: rejectModalOrder.id,
          order_id: rejectModalOrder.id,
          reason: rejectReason.trim() || "Payment verification failed",
        }),
      });

      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data?.error || "Failed to reject manual order");
      }

      toast.success(data.message || `Order ${rejectModalOrder.code} rejected and inventory hold released.`);
      setRejectModalOrder(null);
      if (selectedDetailOrder?.id === rejectModalOrder.id) {
        setSelectedDetailOrder(null);
      }
      loadOrders(true);
    } catch (err: any) {
      toast.error(err?.message || "Failed to reject order");
    } finally {
      setIsRejecting(false);
    }
  }

  async function handleBatchPurge() {
    if (selectedOrderIds.length === 0) return;
    const count = selectedOrderIds.length;
    const confirmMsg = `Are you sure you want to permanently delete and purge ${count} selected order(s)?\n\nThis will remove orders and delete associated records. Only unfulfilled reservations are released back to AVAILABLE inventory, while already-delivered credentials remain permanently consumed. This action cannot be undone.`;
    if (!window.confirm(confirmMsg)) return;

    setIsPurging(true);
    try {
      const res = await fetch("/api/admin/orders", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ orderIds: selectedOrderIds }),
      });

      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data?.error || "Failed to purge selected orders");
      }

      const deletedIds: string[] =
        Array.isArray(data.deletedIds) && data.deletedIds.length > 0
          ? data.deletedIds.map(String)
          : selectedOrderIds;

      toast.success(`Successfully purged ${deletedIds.length} order(s).`);

      const deletedIdSet = new Set(deletedIds);
      setOrders((prev) => {
        const nextOrders = prev.filter((o) => !deletedIdSet.has(String(o.id)));
        recalcStats(nextOrders);
        return nextOrders;
      });
      setSelectedOrderIds([]);
      router.refresh();
    } catch (err: any) {
      toast.error(err?.message || "Failed to purge orders");
    } finally {
      setIsPurging(false);
    }
  }

  async function handleDeleteSingleOrder(order: OrderRow) {
    const confirmMsg = `Are you sure you want to delete order ${order.code} (#${order.id})?\n\nThis will permanently remove the order and delete associated records. Only unfulfilled reservations are released back to AVAILABLE inventory, while already-delivered credentials remain permanently consumed.`;
    if (!window.confirm(confirmMsg)) return;

    setIsPurging(true);
    try {
      const res = await fetch("/api/admin/orders", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ orderIds: [String(order.id)] }),
      });

      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data?.error || `Failed to delete order ${order.code}`);
      }

      toast.success(`Order ${order.code} deleted.`);

      const idStr = String(order.id);
      setOrders((prev) => {
        const nextOrders = prev.filter((o) => String(o.id) !== idStr);
        recalcStats(nextOrders);
        return nextOrders;
      });
      setSelectedOrderIds((prev) => prev.filter((id) => id !== idStr));
      router.refresh();
    } catch (err: any) {
      toast.error(err?.message || "Failed to delete order");
    } finally {
      setIsPurging(false);
    }
  }

  function getRemainingDays(expirationDateStr?: string | null) {
    if (!expirationDateStr) return "No Warranty";
    const exp = new Date(expirationDateStr);
    const diffDays = Math.ceil((exp.getTime() - Date.now()) / (1000 * 60 * 60 * 24));
    if (diffDays < 0) return "Expired";
    if (diffDays === 0) return "Expires Today";
    return `${diffDays} Days Left`;
  }

  const filteredOrders = orders.filter((ord) => {
    if (!searchQuery.trim()) return true;
    const q = searchQuery.toLowerCase();
    return (
      ord.code?.toLowerCase().includes(q) ||
      ord.customer_username?.toLowerCase().includes(q) ||
      String(ord.customer_id).includes(q) ||
      ord.buyer_email?.toLowerCase().includes(q) ||
      ord.buyer_telegram?.toLowerCase().includes(q) ||
      ord.payment_reference?.toLowerCase().includes(q) ||
      ord.payment_sender_name?.toLowerCase().includes(q) ||
      ord.payment_channel?.toLowerCase().includes(q) ||
      ord.product_snapshot?.name?.toLowerCase().includes(q) ||
      ord.assigned_account_email?.toLowerCase().includes(q) ||
      ord.assigned_credentials_preview?.toLowerCase().includes(q)
    );
  });

  const isPendingVerificationTab = stateFilter === "PENDING_MANUAL_VERIFICATION";

  return (
    <div className="space-y-5 w-full">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 border-b border-border pb-5">
        <div>
          <div className="flex items-center space-x-2.5">
            <div className="w-8 h-8 rounded-xl bg-sky-500/10 border border-sky-500/25 flex items-center justify-center">
              <ShoppingBag className="w-4 h-4 text-sky-500" />
            </div>
            <h1 className="text-xl sm:text-2xl font-semibold tracking-tight text-foreground font-sans">
              Orders
            </h1>
          </div>
          <p className="text-sm text-muted-foreground mt-1">
            Search customer orders, manual payment verification queue, and assigned credentials.
          </p>
        </div>

        <div className="flex items-center space-x-3">
          <button
            onClick={() => { void loadOrders(); }}
            disabled={loading}
            className="flex items-center space-x-1.5 px-3 py-2 rounded-xl bg-card border border-border hover:border-border/80 text-xs font-medium text-foreground transition-colors cursor-pointer"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${loading ? "animate-spin text-sky-400" : ""}`} />
            <span>Sync</span>
          </button>
        </div>
      </div>

      {/* Metrics Row */}
      <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
        <button
          type="button"
          onClick={() => setStateFilter("ALL")}
          className={`p-4 rounded-2xl border text-left transition-all backdrop-blur-sm cursor-pointer ${
            stateFilter === "ALL"
              ? "bg-accent border-accent-foreground/20 shadow-sm"
              : "bg-card border-border hover:border-border/80"
          }`}
        >
          <div className="text-xs font-medium text-muted-foreground">Total Orders</div>
          <div className="text-2xl font-bold text-foreground mt-1 font-mono">{stats.total}</div>
          <div className="text-[11px] text-muted-foreground/80 mt-0.5">Recorded orders</div>
        </button>

        <button
          type="button"
          onClick={() => setStateFilter("PENDING_MANUAL_VERIFICATION")}
          className={`p-4 rounded-2xl border text-left transition-all backdrop-blur-sm relative overflow-hidden ${
            stateFilter === "PENDING_MANUAL_VERIFICATION"
              ? "bg-amber-500/10 border-amber-500/50 shadow-lg shadow-amber-950/40"
              : "bg-card border-border hover:border-amber-500/40"
          }`}
        >
          <div className="flex items-center justify-between">
            <div className="text-xs font-medium text-amber-400">Pending Verification</div>
            {stats.verificationPending > 0 && (
              <span className="relative flex h-2.5 w-2.5">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-amber-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-amber-500"></span>
              </span>
            )}
          </div>
          <div className="text-2xl font-bold text-amber-400 mt-1 font-mono">{stats.verificationPending || 0}</div>
          <div className="text-[11px] text-amber-400/80 mt-0.5">Manual proof queue</div>
        </button>

        <button
          type="button"
          onClick={() => setStateFilter("DELIVERED")}
          className={`p-4 rounded-2xl border text-left transition-all backdrop-blur-sm ${
            stateFilter === "DELIVERED"
              ? "bg-emerald-500/10 border-emerald-500/50 shadow-md"
              : "bg-card border-border hover:border-emerald-500/40"
          }`}
        >
          <div className="text-xs font-medium text-emerald-400">Delivered &amp; Active</div>
          <div className="text-2xl font-bold text-emerald-400 mt-1 font-mono">{stats.delivered}</div>
          <div className="text-[11px] text-emerald-400/80 mt-0.5">Credentials delivered</div>
        </button>

        <button
          type="button"
          onClick={() => setStateFilter("REPLACED")}
          className={`p-4 rounded-2xl border text-left transition-all backdrop-blur-sm ${
            stateFilter === "REPLACED"
              ? "bg-amber-500/10 border-amber-500/50 shadow-md"
              : "bg-card border-border hover:border-amber-500/40"
          }`}
        >
          <div className="text-xs font-medium text-amber-400">Warranty Swaps</div>
          <div className="text-2xl font-bold text-amber-400 mt-1 font-mono">{stats.replaced}</div>
          <div className="text-[11px] text-amber-400 mt-0.5">Accounts replaced</div>
        </button>

        <button
          type="button"
          onClick={() => setStateFilter("PROCESSING")}
          className={`p-4 rounded-2xl border text-left transition-all backdrop-blur-sm ${
            stateFilter === "PROCESSING"
              ? "bg-sky-500/10 border-sky-500/50 shadow-md"
              : "bg-card border-border hover:border-sky-500/40"
          }`}
        >
          <div className="text-xs font-medium text-sky-400">Pending Fulfillment</div>
          <div className="text-2xl font-bold text-sky-400 mt-1 font-mono">{stats.pending}</div>
          <div className="text-[11px] text-sky-400/80 mt-0.5">Awaiting delivery</div>
        </button>
      </div>

      {/* Search & Tabs */}
      <div className="space-y-3">
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3">
          <div className="w-full sm:w-80 relative">
            <Search className="w-3.5 h-3.5 text-zinc-400 absolute left-3 top-1/2 -translate-y-1/2" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search code, ref, buyer, product..."
              className="w-full pl-8 pr-3 py-2 rounded-xl bg-card border border-border text-xs text-foreground placeholder:text-muted-foreground focus:outline-none focus:border-sky-500/50 font-mono transition-colors"
            />
          </div>

          <div className="overflow-x-auto pb-1">
            <AnimatedTabs
              tabs={FILTER_TABS}
              activeTab={stateFilter}
              onChange={(id) => setStateFilter(id)}
              layoutId="orderFilterTabs"
            />
          </div>
        </div>
      </div>

      {/* Batch Action Toolbar */}
      {selectedOrderIds.length > 0 && (
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 p-3.5 px-4 rounded-2xl bg-card/95 border border-rose-500/40 shadow-xl backdrop-blur-md animate-in fade-in duration-200">
          <div className="flex items-center space-x-2.5">
            <span className="flex h-2.5 w-2.5 relative">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-rose-400 opacity-75"></span>
              <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-rose-500"></span>
            </span>
            <span className="text-xs text-foreground">
              Selected: <strong className="font-mono text-foreground text-sm">{selectedOrderIds.length}</strong> order{selectedOrderIds.length === 1 ? "" : "s"}
            </span>
          </div>
          <div className="flex items-center space-x-2">
            <button
              type="button"
              onClick={() => setSelectedOrderIds([])}
              className="px-3 py-1.5 rounded-xl bg-muted hover:bg-muted/80 text-foreground text-xs font-semibold transition-colors cursor-pointer border border-border"
            >
              Deselect All
            </button>
