                      }
                      onChange={(e) => {
                        if (e.target.checked) {
                          const allIds = filteredOrders.map((o) => String(o.id));
                          setSelectedOrderIds((prev) => Array.from(new Set([...prev, ...allIds])));
                        } else {
                          const filteredSet = new Set(filteredOrders.map((o) => String(o.id)));
                          setSelectedOrderIds((prev) => prev.filter((id) => !filteredSet.has(id)));
                        }
                      }}
                      className="w-3.5 h-3.5 rounded border-border bg-card text-rose-500 focus:ring-rose-500 cursor-pointer accent-rose-500"
                    />
                  </th>
                  <th className="w-[11%] px-3 py-2">Order</th>
                  <th className="w-[12%] px-3 py-2">Customer</th>
                  <th className="w-[13%] px-3 py-2">Product</th>
                  <th className="w-[11%] px-3 py-2">Credentials</th>
                  <th className="w-[9%] px-3 py-2">Date</th>
                  <th className="w-[8%] px-3 py-2">Warranty</th>
                  <th className="w-[16%] px-3 py-2">Status</th>
                  <th className="w-[20%] px-3 py-2 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border">
                {loading ? (
                  <tr>
                    <td colSpan={9} className="px-4 py-12 text-center text-muted-foreground">
                      <Loader2 className="w-5 h-5 animate-spin mx-auto mb-2 text-sky-400" />
                      Connecting to orders ledger...
                    </td>
                  </tr>
                ) : filteredOrders.length === 0 ? (
                  <tr>
                    <td colSpan={9} className="px-4 py-12 text-center text-muted-foreground">
                      <ShoppingBag className="w-8 h-8 mx-auto mb-2 opacity-30" />
                      No customer orders found matching this filter.
                    </td>
                  </tr>
                ) : (
                  filteredOrders.map((ord) => {
                    const isRevealed = revealedPasswords[ord.id] || false;
                    const hasAssigned = Boolean(
                      (ord.units && ord.units.length > 0) ||
                        ord.assigned_account_id ||
                        ord.assigned_account_email ||
                        ord.assigned_account_label
                    );
                    const remainingDays = getRemainingDays(ord.warranty_expiration);
                    const isReplacing = replacingId === ord.id;
                    const isApproving = approvingId === ord.id;
                    const isManualVerification = ord.state === "PENDING_MANUAL_VERIFICATION";

                    const dropdownItems: Array<{
                      label: string;
                      icon: React.ReactNode;
                      onClick: () => Promise<void> | void;
                      disabled: boolean;
                      danger?: boolean;
                    }> = [
                      {
                        label: isReplacing ? "Replacing..." : "1-Click Warranty Replacement",
                        icon: <RotateCcw className="w-3.5 h-3.5 text-amber-400" />,
                        onClick: () => handleWarrantyReplacement(ord),
                        disabled: !hasAssigned || isReplacing,
                      },
                    ];

                    dropdownItems.push({
                      label: "Delete Order",
                      icon: <Trash2 className="w-3.5 h-3.5 text-rose-400" />,
                      onClick: () => handleDeleteSingleOrder(ord),
                      danger: true,
                      disabled: isPurging,
                    });

                    if (isManualVerification) {
                      dropdownItems.unshift(
                        {
                          label: isApproving ? "Approving..." : "Approve & Dispense",
                          icon: <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />,
                          onClick: () => handleApproveManualOrder(ord),
                          disabled: isApproving,
                        },
                        {
                          label: "Reject Order",
                          icon: <RotateCcw className="w-3.5 h-3.5 text-rose-400" />,
                          onClick: () => handleRejectManualOrder(ord),
                          disabled: isApproving,
                        }
                      );
                    } else if (
                      [
                        "PENDING_OWNER",
                        "ACCEPTED",
                        "AWAITING_PAYMENT",
                        "PAYMENT_REVIEW",
                        "PENDING",
                      ].includes(ord.state)
                    ) {
                      dropdownItems.unshift({
                        label: isApproving ? "Delivering..." : "Approve & Deliver Credentials",
                        icon: <Zap className="w-3.5 h-3.5 text-emerald-400" />,
                        onClick: () => handleApproveAndDeliver(ord),
                        disabled: isApproving,
                      });
                    }

                    const isNew = newlyArrivedIds.has(ord.id);

                    return (
                      <tr
                        key={ord.id}
                        className={`transition-all duration-300 group font-sans ${
                          isNew
                            ? "bg-amber-500/25 ring-2 ring-amber-500/80 shadow-lg shadow-amber-950/50 animate-pulse"
                            : "hover:bg-muted/40"
                        }`}
                      >
                        {/* Checkbox */}
                        <td className="w-9 px-3 py-2.5 text-center">
                          <input
                            type="checkbox"
                            aria-label={`Select order ${ord.code}`}
                            checked={selectedOrderIds.includes(String(ord.id))}
                            onChange={(e) => {
                              e.stopPropagation();
                              const idStr = String(ord.id);
                              setSelectedOrderIds((prev) =>
                                e.target.checked ? [...prev, idStr] : prev.filter((id) => id !== idStr)
                              );
                            }}
                            className="w-3.5 h-3.5 rounded border-border bg-card text-rose-600 focus:ring-rose-500 cursor-pointer accent-rose-600"
                          />
                        </td>

                        {/* Order Code & Payment */}
                        <td className="px-3 py-2.5 font-mono">
                          <div className="flex items-center gap-1.5">
                            <button
                              type="button"
                              onClick={() => setSelectedDetailOrder(ord)}
                              className="text-sky-600 dark:text-sky-300 hover:underline font-bold text-xs tracking-tight flex items-center gap-1 group/code cursor-pointer truncate"
                              title="Click to view full Order Details"
                            >
                              <span className="truncate">{ord.code}</span>
                              <ExternalLink className="w-2.5 h-2.5 text-sky-500/60 group-hover/code:text-sky-400 shrink-0" />
                            </button>
                            {isNew && (
                              <span className="px-1 py-0.2 rounded text-[9px] font-bold bg-amber-400 text-neutral-950 uppercase shrink-0">
                                NEW
                              </span>
                            )}
                            <button
                              onClick={() => handleCopy(ord.code, `code_${ord.id}`)}
                              className="text-muted-foreground/60 hover:text-foreground transition-colors cursor-pointer shrink-0"
                              title="Copy order code"
                            >
                              {copiedStates[`code_${ord.id}`] ? (
                                <Check className="w-3 h-3 text-emerald-400" />
                              ) : (
                                <Copy className="w-3 h-3" />
                              )}
                            </button>
                          </div>
                          <div className="flex items-center gap-1 mt-0.5">
                            <span className="px-1.5 py-0.2 rounded text-[10px] font-mono text-muted-foreground bg-muted/60 border border-border/50 uppercase">
                              {ord.payment_channel || "MANUAL"}
                            </span>
                            {ord.payment_reference && (
                              <span
                                className="text-[10px] text-amber-500 dark:text-amber-400 font-mono truncate max-w-[85px]"
                                title={ord.payment_reference}
                              >
                                {ord.payment_reference}
                              </span>
                            )}
                          </div>
                        </td>

                        {/* Customer & Buyer */}
                        <td className="px-3 py-2.5">
                          <div className="flex items-center gap-1 text-xs font-medium text-foreground truncate">
                            <User className="w-3 h-3 text-muted-foreground/70 shrink-0" />
                            <span className="truncate" title={ord.buyer_telegram || `@${ord.customer_username || ord.customer_id}`}>
                              {ord.buyer_telegram || `@${ord.customer_username || ord.customer_id}`}
                            </span>
                          </div>
                          {ord.buyer_email && (
                            <div className="text-[11px] text-muted-foreground flex items-center gap-1 mt-0.5 truncate">
                              <Mail className="w-2.5 h-2.5 text-muted-foreground/70 shrink-0" />
                              <span className="truncate" title={ord.buyer_email}>{ord.buyer_email}</span>
                            </div>
                          )}
                        </td>

                        {/* Product & Price */}
                        <td className="px-3 py-2.5">
                          <div className="font-medium text-xs text-foreground truncate" title={ord.product_snapshot?.name || "Product"}>
                            {ord.product_snapshot?.name || "Product"}
                          </div>
                          <div className="text-[11px] text-muted-foreground font-mono mt-0.5 truncate">
                            ₱{Number(ord.total || 0).toLocaleString()} <span className="opacity-60">&bull; Qty {ord.quantity}</span>
                          </div>
                        </td>

                        <td className="px-3 py-2.5 font-mono">
                          {hasAssigned ? (
                            ord.units && ord.units.length > 1 ? (
                              <div className="flex items-center gap-1.5">
                                <button
                                  type="button"
                                  onClick={() => setSelectedDetailOrder(ord)}
                                  className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[11px] font-mono font-medium bg-amber-500/10 text-amber-400 border border-amber-500/25 hover:bg-amber-500/20 transition-all cursor-pointer"
                                  title="Inspect units"
                                >
                                  <Package className="w-3 h-3 text-amber-400 shrink-0" />
                                  <span>{ord.units.length} Units</span>
                                </button>
                              </div>
                                                        ) : (
                                                          <div className="space-y-0.5 min-w-0">
                                                            <div className="flex items-center gap-1">
                                                              <span className="text-foreground text-xs truncate select-all" title={
                                                                (ord.units && ord.units[0]?.formatted) ||
                                                                ord.assigned_account_email ||
                                                                ord.assigned_account_label ||
                                                                (ord.units && ord.units[0]?.email) ||
                                                                (ord.units && ord.units[0]?.accountUrl) || ""
                                                              }>
                                                                {(ord.units && ord.units[0]?.formatted) ||
                                                                  ord.assigned_account_email ||
                                                                  ord.assigned_account_label ||
                                                                  (ord.units && ord.units[0]?.email) ||
                                                                  (ord.units && ord.units[0]?.accountUrl)}
                                                              </span>
                                                              <button
                                                                onClick={() =>
                                                                  handleCopy(
                                                                    (ord.units && ord.units[0]?.formatted) ||
                                                                      ord.assigned_account_email ||
                                                                      ord.assigned_account_label ||
                                                                      (ord.units && ord.units[0]?.email) ||
                                                                      "",
                                                                    `email_${ord.id}`
                                                                  )
                                                                }
                                                                className="text-muted-foreground/60 hover:text-foreground shrink-0 cursor-pointer"
                                                                title="Copy credential"
                                                              >
                                                                {copiedStates[`email_${ord.id}`] ? (
                                                                  <Check className="w-3 h-3 text-emerald-400" />
                                                                ) : (
                                                                  <Copy className="w-3 h-3" />
                                                                )}
                                                              </button>
                                                            </div>

                                                            {(ord.assigned_account_password || (ord.units && ord.units[0]?.password)) && (
                                                              <div className="flex items-center gap-1 text-[11px]">
                                                                <span className="font-mono text-muted-foreground">
                                                                  {isRevealed ? (
                                                                    <span className="text-amber-500 dark:text-amber-300 font-semibold">
                                                                      {ord.assigned_account_password || ord.units?.[0]?.password}
                                                                    </span>
                                                                  ) : (
                                                                    "••••••••"
                                                                  )}
                                                                </span>
                                                                <button
                                                                  onClick={() => togglePassword(ord.id)}
                                                                  className="text-muted-foreground/60 hover:text-foreground shrink-0 cursor-pointer"
                                                                  title={isRevealed ? "Hide" : "Show"}
                                                                >
                                                                  {isRevealed ? (
                                                                    <EyeOff className="w-2.5 h-2.5 text-amber-500" />
                                                                  ) : (
                                                                    <Eye className="w-2.5 h-2.5" />
                                                                  )}
                                                                </button>
                                                                <button
                                                                  onClick={() =>
                                                                    handleCopy(
                                                                      ord.assigned_account_password || ord.units?.[0]?.password || "",
                                                                      `pwd_${ord.id}`
                                                                    )
                                                                  }
                                                                  className="text-muted-foreground/60 hover:text-foreground shrink-0 cursor-pointer"
                                                                  title="Copy password"
                                                                >
                                                                  {copiedStates[`pwd_${ord.id}`] ? (
                                                                    <Check className="w-2.5 h-2.5 text-emerald-400" />
                                                                  ) : (
                                                                    <Copy className="w-2.5 h-2.5" />
                                                                  )}
                                                                </button>
                                                              </div>
                                                            )}

                                                            {ord.assigned_profile_pin && (
                                                              <div className="text-[10px] text-amber-500 dark:text-amber-400 font-semibold font-mono">
                                                                PIN: {ord.assigned_profile_pin}
                                                              </div>
                                                            )}

                                                            <SupplierOriginTag
                                                              isSupplier={Boolean(
                                                                ord.is_supplier_stock ||
                                                                  (ord.units && ord.units[0]?.is_supplier_stock) ||
                                                                  ord.supplier_id ||
                                                                  ord.supplier_handle
                                                              )}
                                                              supplierHandle={
                                                                ord.supplier_handle ||
                                                                (ord.units && ord.units[0]?.supplier_handle)
                                                              }
                                                            />
                                                          </div>
                                                        )
                                                      ) : (
                                                        <span className="text-[11px] text-rose-500/80 font-medium font-sans">
                                                          Unassigned
                                                        </span>
                                                      )}
                                                    </td>

                        {/* Purchase Time (Compact 2-Line) */}
                        <td className="px-3 py-2.5 font-mono text-xs leading-tight">
                          <div className="text-foreground/90 font-medium">
                            {new Date(ord.created_at).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
                          </div>
                          <div className="text-[10px] text-muted-foreground/70">
                            {new Date(ord.created_at).toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" })}
                          </div>
                        </td>

                        {/* Warranty / Lease */}
                        <td className="px-3 py-2 font-mono text-xs">
                          {isManualVerification ? (
                            <OrderCountdown expiresAt={ord.expires_at} createdAt={ord.created_at} />
                          ) : (
                            <div className="text-[11px] text-muted-foreground font-medium">
                              {remainingDays}
                            </div>
                          )}
                        </td>

                        {/* Status */}
                        <td className="px-3 py-2">
                          <div className="shrink-0 whitespace-nowrap">
                            <StatusBadge status={ord.state} size="sm" />
                          </div>
                        </td>

                        {/* Actions */}
                        <td className="px-3 py-2 text-right font-sans">
                          <div className="flex items-center justify-end gap-1.5 shrink-0 whitespace-nowrap">
                            {isManualVerification && (
                              <div className="flex items-center gap-1">
                                <button
                                  type="button"
                                  onClick={() => handleApproveManualOrder(ord)}
                                  disabled={isApproving}
                                  className="h-6 px-2 rounded bg-emerald-500/15 hover:bg-emerald-500/25 text-emerald-400 text-[11px] font-semibold transition-colors disabled:opacity-50 cursor-pointer"
                                  title="Approve & Dispense Credentials"
                                >
                                  Approve
                                </button>
                                <button
                                  type="button"
                                  onClick={() => handleRejectManualOrder(ord)}
                                  disabled={isApproving}
                                  className="h-6 px-1.5 rounded text-rose-400/80 hover:text-rose-400 hover:bg-rose-500/10 text-[11px] font-semibold transition-colors disabled:opacity-50 cursor-pointer"
                                  title="Reject Manual Order"
                                >
                                  Reject
                                </button>
                              </div>
                            )}
                            {hasAssigned && (
                              <button
                                type="button"
                                onClick={() => handleWarrantyReplacement(ord)}
                                disabled={isReplacing}
                                className="h-6 px-2 rounded bg-amber-500/10 hover:bg-amber-500/20 text-amber-400 text-[11px] font-medium transition-colors disabled:opacity-50 flex items-center gap-1 cursor-pointer"
                                title="1-Click Warranty Replacement"
                              >
                                <RotateCcw
                                  className={`w-3 h-3 ${isReplacing ? "animate-spin" : ""}`}
                                />
                                <span>Swap</span>
                              </button>
                            )}
                            <ActionDropdown items={dropdownItems} />
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Order Details & Proof Inspection Modal */}
      <OrderDetailsModal
        order={selectedDetailOrder}
        isOpen={Boolean(selectedDetailOrder)}
        onClose={() => setSelectedDetailOrder(null)}
        onApprove={handleApproveManualOrder}
        onReject={handleRejectManualOrder}
        onWarrantyReplacement={handleWarrantyReplacement}
        onPurge={handleDeleteSingleOrder}
        isApproving={approvingId === selectedDetailOrder?.id}
        replacingId={replacingId}
      />

      {/* Reject Order Confirmation Dialog Modal */}
      <AnimatedModal
        isOpen={Boolean(rejectModalOrder)}
        onClose={() => {
          if (!isRejecting) setRejectModalOrder(null);
        }}
        maxWidth="max-w-md"
        title={
          <div className="flex items-center gap-2 text-rose-500 font-semibold text-sm">
            <AlertCircle className="w-4 h-4 shrink-0" />
            <span>Reject Order {rejectModalOrder?.code}</span>
          </div>
        }
        description={
          <span className="text-xs text-muted-foreground">
            Customer: @{rejectModalOrder?.customer_username || rejectModalOrder?.customer_id} &bull; ₱{Number(rejectModalOrder?.total || 0).toLocaleString()}
          </span>
        }
      >
        <div className="space-y-4 pt-1 font-sans">
          <p className="text-xs text-muted-foreground leading-relaxed">
            Select or enter a reason for rejecting this payment submission. The reserved inventory hold will be released and the customer will receive this status update.
          </p>

          {/* Quick preset chips */}
          <div className="space-y-1.5">
            <span className="text-[11px] font-medium text-muted-foreground">Quick Reasons:</span>
            <div className="flex flex-wrap gap-1.5">
              {[
                "Payment proof could not be verified in e-wallet.",
                "Reference # not found in transaction history.",
                "Amount paid does not match order total.",
                "Unreadable or invalid proof image.",
                "Duplicate payment receipt submitted.",
              ].map((preset) => (
                <button
                  key={preset}
                  type="button"
                  onClick={() => setRejectReason(preset)}
                  className={`text-[11px] px-2 py-1 rounded-md transition-colors cursor-pointer text-left border ${
                    rejectReason === preset
                      ? "bg-rose-500/15 text-rose-400 border-rose-500/40"
                      : "bg-muted/50 hover:bg-muted text-muted-foreground border-border"
                  }`}
                >
                  {preset}
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-1.5">
            <label htmlFor="reject-reason-input" className="text-[11px] font-medium text-foreground">
              Notification Reason to Customer:
            </label>
            <textarea
              id="reject-reason-input"
              rows={3}
              value={rejectReason}
              onChange={(e) => setRejectReason(e.target.value)}
              placeholder="Enter explanation for customer..."
              className="w-full text-xs rounded-lg border border-border bg-card px-3 py-2 text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-rose-500 resize-none font-sans"
            />
          </div>

          <div className="flex items-center justify-end gap-2 pt-2 border-t border-border">
            <button
              type="button"
              disabled={isRejecting}
              onClick={() => setRejectModalOrder(null)}
              className="px-3 py-1.5 text-xs rounded-lg border border-border hover:bg-muted text-muted-foreground transition-colors cursor-pointer disabled:opacity-50"
            >
              Cancel
            </button>
            <button
              type="button"
              disabled={isRejecting || !rejectReason.trim()}
              onClick={submitRejectManualOrder}
              className="px-3.5 py-1.5 text-xs font-medium rounded-lg bg-rose-600 hover:bg-rose-500 text-white transition-colors flex items-center gap-1.5 shadow-sm cursor-pointer disabled:opacity-50"
            >
              {isRejecting ? (
                <>
                  <Loader2 className="w-3.5 h-3.5 animate-spin" />
                  <span>Rejecting...</span>
                </>
              ) : (
                <span>Confirm Rejection</span>
              )}
            </button>
          </div>
        </div>
      </AnimatedModal>
    </div>
  );
}

"use client";

import React, { useState, useEffect, useMemo, useCallback, useRef } from "react";
import { useRouter } from "next/navigation";
import {
  ShoppingBag,
  RefreshCw,
  Loader2,
  CheckCircle2,
  RotateCcw,
  Eye,
  EyeOff,
  Copy,
  Check,
  User,
  ShieldCheck,
  Boxes,
  Smartphone,
  Wallet,
  Calendar,
  Send,
  Zap,
  Search,
  Clock,
  AlertTriangle,
  Building2,
  ExternalLink,
  Mail,
  MessageCircle,
  XCircle,
  CreditCard,
  Trash2,
  Package,
  AlertCircle,
  Download,
} from "lucide-react";
import { useToast } from "@/app/components/Toast";
import { AnimatedTabs } from "@/components/ui/tabs";
import { StatusBadge } from "@/components/ui/badge";
import { ActionDropdown } from "@/components/ui/dropdown-menu";
import { AnimatedModal } from "@/components/ui/modal";
import { useLiveSync, playNotificationSound, invalidateResource } from "@/src/hooks/use-live-sync";
import { useQuery, keepPreviousData, useQueryClient } from "@tanstack/react-query";
import { queryKeys } from "@/src/lib/query-keys";
import { OrderDetailsModal } from "@/components/admin/OrderDetailsModal";
